536	  function formatBRL(n){
537	    var partes = Number(n).toFixed(2).split(".");
538	    var inteiro = partes[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".");
539	    return "R$ " + inteiro + "," + partes[1];
540	  }
541	
542	  function formatDataHora(d){
543	    function pad(n){ return String(n).padStart(2, "0"); }
544	    return pad(d.getDate()) + "/" + pad(d.getMonth() + 1) + "/" + d.getFullYear() + " " + pad(d.getHours()) + ":" + pad(d.getMinutes());
545	  }
