547	  function inserirNoCursor(textarea, texto){
548	    var start = typeof textarea.selectionStart === "number" ? textarea.selectionStart : textarea.value.length;
549	    var end = typeof textarea.selectionEnd === "number" ? textarea.selectionEnd : start;
550	    var valor = textarea.value;
551	    textarea.value = valor.slice(0, start) + texto + valor.slice(end);
552	    var pos = start + texto.length;
553	    textarea.focus();
554	    try{ textarea.setSelectionRange(pos, pos); }catch(e){}
555	  }
