587	    { id: "concorrente-barato", nomeSugerido: "Concorrente mais barato", fraseOriginal: "vi mais barato na concorrente", origemFrase: "generate_dataset.py:39 (OBJECOES)" },
588	    { id: "caro-pro-carro", nomeSugerido: "Caro para esse carro", fraseOriginal: "achei caro pra esse carro", origemFrase: "generate_dataset.py:39 (OBJECOES)" }
