606	  function carregarEstado(cfg, chave){
607	    var base = estadoPadrao(cfg);
608	    var salvo;
609	    try{ salvo = lsGet(chave); }catch(e){ salvo = null; }
610	    if(!salvo || typeof salvo !== "object"){ return base; }
611	    try{
612	      var estado = estadoPadrao(cfg);
613	      if(typeof salvo.nome === "string" && salvo.nome.trim()) estado.nome = salvo.nome;
614	      if(Array.isArray(salvo.frases) && salvo.frases.length){
615	        var temHistorico = salvo.frases.some(function(f){ return f && f.origem === "historico"; });
616	        estado.frases = temHistorico ? salvo.frases : base.frases.concat(salvo.frases);
617	      }
618	      if(typeof salvo.resposta === "string") estado.resposta = salvo.resposta;
619	      if(salvo.argumentos && typeof salvo.argumentos === "object"){
620	        ARGUMENTOS.forEach(function(a){ estado.argumentos[a.id] = !!salvo.argumentos[a.id]; });
621	      }
622	      if(typeof salvo.tentativas === "string" || typeof salvo.tentativas === "number") estado.tentativas = String(salvo.tentativas);
623	      estado.publicado = !!salvo.publicado;
