807	      if(analise.digitoForaDeMarcador) faltando.push("Há número fora de marcador.");
808	      analise.desconhecidos.forEach(function(d){ faltando.push("Marcador desconhecido: {{" + d + "}}."); });
809	      var algumArgumento = ARGUMENTOS.some(function(a){ return !!state.argumentos[a.id]; });
810	      if(!algumArgumento) faltando.push("Marque pelo menos 1 argumento.");
811	      var tentNum = parseInt(state.tentativas, 10);
812	      if(state.tentativas === "" || isNaN(tentNum) || tentNum < 1 || tentNum > 5){
813	        faltando.push("Preencha as tentativas entre 1 e 5.");
814	      }
815	
816	      elBtnPublicar.disabled = faltando.length > 0;
817	      elFaltando.innerHTML = "";
818	      if(faltando.length){
819	        faltando.forEach(function(f){
820	          var li = document.createElement("li");
821	          li.textContent = f;
822	          elFaltando.appendChild(li);
823	        });
824	        elFaltando.hidden = false;
825	      } else {
826	        elFaltando.hidden = true;
827	      }
828	
829	      if(state.publicado){
830	        elSelo.textContent = "Publicado";
831	        elSelo.className = "obj-selo publicado";
832	      } else if(state.versao > 0){
833	        elSelo.textContent = "Rascunho (alterações não publicadas)";
834	        elSelo.className = "obj-selo rascunho";
835	      } else {
836	        elSelo.textContent = "Rascunho";
837	        elSelo.className = "obj-selo rascunho";
838	      }
839	
840	      if(state.salvoEm){
841	        elVersao.textContent = "versão " + state.versao + " · salvo em " + state.salvoEm;
842	        elVersao.hidden = false;
843	      } else {
844	        elVersao.hidden = true;
845	      }
846	    }
847	
848	    elNome.value = state.nome;
849	    elResposta.value = state.resposta;
850	    elTentativas.value = state.tentativas;
851	    renderTags();
852	
853	    elNome.addEventListener("input", function(){
854	      state.nome = elNome.value;
855	      marcarEditado();
856	      atualizarTudo();
857	    });
858	    elAddFrase.addEventListener("keydown", function(e){
859	      if(e.key === "Enter"){
860	        e.preventDefault();
861	        var v = elAddFrase.value.trim();
862	        if(v){
863	          state.frases.push({ texto: v, origem: "acrescentada" });
864	          elAddFrase.value = "";
865	          marcarEditado();
866	          renderTags();
867	          atualizarTudo();
868	        }
869	      }
870	    });
871	    elResposta.addEventListener("input", function(){
872	      state.resposta = elResposta.value;
873	      marcarEditado();
874	      atualizarTudo();
875	    });
876	    elTentativas.addEventListener("input", function(){
877	      state.tentativas = elTentativas.value;
878	      marcarEditado();
879	      atualizarTudo();
880	    });
881	    elBtnSalvar.addEventListener("click", function(){
882	      state.salvoEm = formatDataHora(new Date());
883	      lsSet(chave, state);
884	      atualizarTudo();
885	    });
886	    elBtnPublicar.addEventListener("click", function(){
887	      var analise = analisarResposta(state.resposta || "");
888	      var algumArgumento = ARGUMENTOS.some(function(a){ return !!state.argumentos[a.id]; });
889	      var tentNum = parseInt(state.tentativas, 10);
890	      var ok = (state.resposta || "").trim() && !analise.digitoForaDeMarcador && !analise.desconhecidos.length &&
891	        algumArgumento && !isNaN(tentNum) && tentNum >= 1 && tentNum <= 5;
892	      if(!ok) return;
893	      state.publicado = true;
894	      state.versao = (state.versao || 0) + 1;
895	      state.salvoEm = formatDataHora(new Date());
896	      lsSet(chave, state);
897	      atualizarTudo();
898	    });
899	
900	    atualizarTudo();
901	  }
